      "key_provisions": "กำหนดผังกระบวนงาน (Process Flow) และกรอบเวลาปฏิบัติงานจริงตามปฏิทินงบประมาณล่วงหน้า 2 ปี (ปี T ถึง T+2): (1) ก.ค.–ส.ค.(T) จัดทำกรอบวงเงินและทบทวนหลักเกณฑ์เสนอ กสว., (2) ก.ย.–ต.ค.(T->T+1, ~45 วัน) เปิดรับคำขอผ่านระบบ NRIIS (FF/SF) และ STARS (ST), (3) ต.ค.–พ.ย.(T+1, ~20 วัน) สกสว. กลั่นกรองคำขอ, (4) ธ.ค.–ม.ค.(T+1) เสนอ กสว. และ คกก.พิจารณางบประมาณ ม.12(2) และ Sign-off E-budgeting ส่งสำนักงบประมาณ, (5) เม.ย.–พ.ค.(T+1) จัดสรรขั้น Pre-ceiling ให้หน่วยงานปรับคำชี้แจงใน 15 วัน และตรวจใน 10 วัน, (6) มิ.ย.–ส.ค.(T+1) ชี้แจง กมธ.งบประมาณ ปรับยอดตามมติ กมธ. และแจ้งจัดสรรเพื่อทำคำรับรองฯ (พร้อม SOP ย่อย 1.1–1.3 และ 2.1–2.3)",
