      "text": "เพื่อให้เป็นไปตามกฎหมายว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ การจัดซื้อจัดจ้างเพื่อการวิจัยและพัฒนา การสร้างนวัตกรรม และ",
