      "text": "เพื่อประโยชน์ในการบูรณาการ บริหารจัดการ และวิเคราะห์ สังเคราะห์ข้อมูล การวิจัยและนวัตกรรมในภาพรวมของประเทศ ให้หน่วยงานในระบบวิจัยแ",
      "url": "https://drive.google.com/file/d/115RIHyhH_S-Xl0BPxQNTrLd4GREUl-gM/view?usp=drivesdk"
