      "text": "ให้สถาบันอุดมศึกษาแจ้งหรือเชื่อมโยงข้อมูลการวิจัยและนวัตกรรมและหัวข้อ วิทยานิพนธ์ที่จะด าเนินการในระดับบัณฑิตศึกษาของนิสิตหรือนักศ",
