      "text": "ให้ส านักงานการวิจัยแห่งชาติจัดท าฐานข้อมูลด้านวิทยาศาสตร์ วิจัยและ นวัตกรรมของประเทศ เพื่อประโยชน์ในการด าเนินการตามวรรคหนึ่ง ให้",
