      "text": "การอ้างอิงข้อมูลด้านวิทยาศาสตร์ วิจัยและนวัตกรรมของประเทศ ให้อ้างอิง จากฐานข้อมูลตามมาตรา 24 ข้อมูลจากฐานข้อมูลอื่นของหน่วยงานในระ",
