      "text": "ภายใต้บังคับมาตรา 22 วรรคสี่และวรรคห้า ส านักงานการวิจัยแห่งชาติ สอวช. และ สกสว. อาจเปิดเผยข้อมูลในฐานข้อมูล ตลอดจนรายงานผลการวิเค",
