      "text": "ให้กระทรวงและ สกสว. ส่งเสริมและสนับสนุนให้บุคคล คณะบุคคล ชุมชน หน่วยงานของรัฐ หรือหน่วยงานภาคเอกชนน าผลงานวิจัยและนวัตกรรมไปใช้ประ",
